{"path": "units/intervals/intervals.py", "content": """"闭区间工具（整数端点，lo <= hi）。"""


class Impl:
    def merge(self, ranges, gap=0):
        """合并闭区间：按 lo 升序排序后，若相邻两段之间**缺失的整数个数**
        （next.lo - prev.hi - 1）小于等于 gap 就合并。返回 [(lo, hi), ...] 升序；空输入返回 []。"""
        if not ranges:
            return []
        ordered = sorted((min(lo, hi), max(lo, hi)) for lo, hi in ranges)
        merged = [list(ordered[0])]
        for lo, hi in ordered[1:]:
            last = merged[-1]
            if lo - last[1] - 1 <= gap:
                if hi > last[1]:
                    last[1] = hi
            else:
                merged.append([lo, hi])
        return [(lo, hi) for lo, hi in merged]

    def subtract(self, ranges, hole):
        """从 ranges 中挖去闭区间 hole：返回剩下的闭区间（升序）。与 hole 不相交的段原样保留，
        被完全覆盖的段消失，横跨 hole 的段分裂成两段。"""
        hole_lo, hole_hi = min(hole), max(hole)
        result = []
        for lo, hi in self.merge(ranges):
            if hi < hole_lo or lo > hole_hi:
                result.append((lo, hi))
                continue
            if lo < hole_lo:
                result.append((lo, hole_lo - 1))
            if hi > hole_hi:
                result.append((hole_hi + 1, hi))
        return result

    def total_length(self, ranges):
        """ranges 覆盖的整数个数之和（闭区间含端点；重叠只算一次）。"""
        return sum(hi - lo + 1 for lo, hi in self.merge(ranges))
"}

{"path": "units/flags/flags.py", "content": """"命令行风格的参数解析。"""


class Impl:
    def parse(self, argv):
        """返回 {"values": {...}, "flags": {...}, "positional": [...]}：
        - 不以 "-" 开头、或正好是 "-" 的项，按出现顺序进 positional。
        - `--` 之后的所有项都是位置参数（`--` 自己不出现在结果里）。
        - `--key=value` 与 `--key value` 都是键值对，键是 key。
        - `--key` 后面没有可用值（到结尾，或后面紧跟另一个 "--" 开头的项）时它是开关。
        - `-abc` 是三个开关 a、b、c。
        - values 的每个值是**列表**，重复的键按出现顺序累积；开关重复出现仍是 True。"""
        values = {}
        flags = {}
        positional = []
        only_positional = False
        i = 0
        while i < len(argv):
            arg = argv[i]
            if only_positional:
                positional.append(arg)
                i += 1
                continue
            if arg == "--":
                only_positional = True
                i += 1
                continue
            if arg.startswith("--"):
                body = arg[2:]
                if "=" in body:
                    key, value = body.split("=", 1)
                    values.setdefault(key, []).append(value)
                    i += 1
                    continue
                key = body
                if i + 1 < len(argv) and not argv[i + 1].startswith("--"):
                    values.setdefault(key, []).append(argv[i + 1])
                    i += 2
                else:
                    flags[key] = True
                    i += 1
                continue
            if arg.startswith("-") and arg != "-":
                for ch in arg[1:]:
                    flags[ch] = True
                i += 1
                continue
            positional.append(arg)
            i += 1
        return {"values": values, "flags": flags, "positional": positional}
"}
